GOLDEN_CLOSING = "یہ ستارہ والا گولڈن ٹاپک ہے۔ امتحان میں تعریف، خاکہ یا جدول، اور ایک روزمرہ مثال تینوں لکھو۔"
NORMAL_CLOSING = "انگریزی متن اسکرین پر رہنے دیجیے — اصطلاحیں انگریزی میں یاد کریں، سمجھ اردو لیکچر سے پکی کریں۔ اللہ حافظ۔"
QA_CLOSING = "پہلے تصور پڑھو، پھر تفریق کا جدول، پھر طویل جواب کی ساخت۔ آخر میں ایم سی کیو سے خود آزمائی کرو۔"


def _norm(text: str) -> str:
    return " ".join((text or "").lower().replace("★", " ").split())


def match_bodies(title: str, extra: str = "") -> list[str]:
    blob = _norm(f"{title} {extra}")
    found: list[str] = []
    seen: set[str] = set()
    for needle, body in TOPIC_BODY:
        if needle in blob and body not in seen:
            found.append(body)
            seen.add(body)
        if len(found) >= 3:
            break
    return found


def compose_lecture(
    book_id: str,
    chapter_index: int,
    chapter_title: str,
    topic_title: str,
    english_excerpt: str,
    golden: bool,
    kind: str,
) -> str:
    intro = CHAPTER_INTRO.get((book_id, chapter_index), "السلام علیکم۔ آج کی کمپیوٹر سائنس لیکچر شروع کرتے ہیں۔")
    topic_line = f"موضوع ہے: {topic_title}۔ باب کا عنوان ہے {chapter_title}۔"
    bodies = match_bodies(topic_title, english_excerpt[:800])
    if not bodies:
        bodies = [
            "اس صفحے کا انگریزی متن بورڈ کے الفاظ میں لکھا گیا ہے۔ میں اصطلاحیں کھول کر سمجھا رہا ہوں تاکہ آپ لکھ سکیں اور بول سکیں۔",
            "پہلے تعریف پڑھو، پھر مثال، پھر موازنہ۔ جو فارمولا یا جدول نظر آئے اسے ایک بار نقل کر کے یاد کرو۔",
        ]
    closing = GOLDEN_CLOSING if golden else (QA_CLOSING if kind == "qa" else NORMAL_CLOSING)
    parts = [intro, topic_line, *bodies, closing]
    return " ".join(parts)
